    let seeded = app.transact_for_tests(|tx| -> Result<(), std::io::Error> {
        for ws in [1u64, 2] {
            let id = Id::<Workspace>::from_raw(ws);
            if tx.get(id)?.is_none() {
                tx.put(&Workspace {
                    id,
                    name: format!("workspace {ws}"),
